epicSlot('gate', 'digger').push(
{ title:'성문 — 둘이 두드린다',
  text:`아래가 비었는지는 두드려서 안다.<br><br>
    혼자 두드리면 두드리는 소리에 듣는 소리가 묻힌다.<br>
    하나가 치고 하나가 들어야 한다.<br><br>
    듣는 쪽은 떨어져 있어야 한다.`,
  opts:[
    { l:'① 동료가 두드린다.', co:'sync',
      coOpt:{ ask:'바닥을 발뒤꿈치로 쳐 주십시오. 제가 떨어져서 듣겠습니다.', sec:60, p:1000,
        text:`치는 쪽은 자기 소리를 못 듣는다.`,
        doneText:`저쪽이 한 칸씩 쳤다. 이쪽은 열 걸음 떨어져 들었다.<br><br>아치 바로 아래만 울린다. 나머지는 꽉 찼다.<br>울리는 데가 딱 한 칸이다.<br><br>사람 하나 들어갈 크기다.<br>표시만 하고 안 팠다. 저쪽이 왜 안 파냐고 물었다. 대답을 안 했다.`,
        failText:`혼자 치고 혼자 들었다.<br><br>치는 소리가 귀에 남아서 울림이 안 잡힌다.<br>어디가 빈지 모르겠다.` },
      good:`빈 칸을 찾았다.`, bad:`못 찾았다.`, flag:'soundedTheFloor' },
    { l:'② 메운 흙의 굳기를 견준다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`메운 데와 주변 흙을 눌러 견줬다.<br><br>맞췄다. 메운 쪽이 훨씬 무르다.<br>안에서 다지면 이렇게 된다. 밖에서 다지면 단단해진다.<br><br>안에서 메웠다는 뜻이다. 나가면서 뒤를 막았다.`, flag:'packedFromInside',
      bad:`굳기가 자리마다 다르다.<br><br>누를 때마다 바뀐다. 기준이 안 선다.<br>그만뒀다.` }
  ] }
);

epicSlot('grave', 'digger').push(
{ title:'묘지 — 둘이 판다',
  text:`굴은 둘이 판다.<br><br>
    하나가 파고 하나가 흙을 받는다.<br>
    혼자 파면 파낸 흙이 쌓여 길을 막는다.<br><br>
    막히면 못 나온다.`,
  opts:[
    { l:'① 동료가 흙을 받는다.', co:'sync',
      coOpt:{ ask:'제가 퍼내면 받아서 옆에 쌓아 주십시오. 입구는 비워 두시고.', sec:60, p:1000,
        text:`파낸 흙이 쌓이면 길이 막힌다.`,
        doneText:`봉분 옆으로 팠다. 저쪽이 흙을 받아 냈다.<br><br>입구가 안 막혔다. 언제든 나올 수 있었다.<br>한 팔 깊이에서 닿았다. 관이 아니다. 나무판이다.<br><br>덮개다. 관 위에 덮개를 하나 더 깔았다.<br>안 열었다. 메우고 나왔다. 둘이 메우니 금방이었다.`,
        failText:`혼자 팠다. 파낸 흙이 뒤에 쌓인다.<br><br>반쯤 파고 나오려니 흙이 막는다.<br>기어 나왔다. 옷이 흙투성이가 됐다.` },
      good:`안 막혔다.`, bad:`기어 나왔다.`, flag:'foundPlank' },
    { l:'② 봉분 높이를 견준다.', mini:'scale', miniOpt:{ p:750, target:19, pool:[2,3,5,6,8,10] },
      good:`스물셋 높이를 견줬다.<br><br>맞췄다. 전부 같다. 한 뼘.<br>같은 사람이 같은 날 같은 깊이로 묻었다.<br><br>다만 하나만 조금 높다. 그것만 나중에 덮었다.`, flag:'oneHigher',
      bad:`높이가 계속 낮아진다.<br><br>재는 동안. 스물셋이 전부.<br>그만뒀다.` }
  ] }
);

epicSlot('village', 'digger').push(
{ title:'빈 마을 — 둘이 파 본다',
  text:`마당에 얕게 묻힌 게 있다.<br><br>
    혼자 파면 판 자리를 못 메운다. 팔이 모자란다.<br>
    둘이면 파고 바로 메운다.<br><br>
    메우는 게 파는 것보다 중요하다.`,
  opts:[
    { l:'① 동료와 하나만 파고 메운다.', co:'handoff',
      coOpt:{ ask:'하나만 파 보겠습니다. 바로 메워야 하니 흙을 잡고 계십시오.', sec:60, p:1000,
        text:`메우는 게 파는 것보다 중요하다.`,
        doneText:`한 마당을 팠다. 얕다. 금방 나온다.<br><br>천에 싼 나무패다. 문패다. 이름이 깎여 있다.<br>저쪽이 흙을 부었다. 바로 메워졌다.<br><br>판 자국이 안 남았다. 굴착꾼은 판 자국을 안 남긴다.<br>그게 오래 하는 방법이다.`,
        failText:`혼자 팠다. 문패가 나왔다.<br><br>메우려니 흙이 모자란다. 파낸 흙이 흩어졌다.<br>판 자국이 남았다.` },
      good:`자국이 안 남았다.`, bad:`자국이 남았다.`, flag:'dugAndFilled' },
    { l:'② 마당 흙의 나이를 견준다.', mini:'scale', miniOpt:{ p:750, target:21, pool:[3,4,6,7,9,10] },
      good:`마당마다 흙이 앉은 정도를 견줬다.<br><br>맞췄다. 스물둘이 같다. 같은 날.<br>단단한 한 마당만 훨씬 오래됐다.<br><br>닫힌 집 마당이다. 거기는 아주 전에 팠다.`, flag:'oneMuchOlder',
      bad:`나이가 안 잡힌다.<br><br>마당마다 흙이 다르다. 견줄 기준이 없다.<br>그만뒀다.` }
  ] }
);

epicSlot('castle', 'digger').push(
{ title:'성 — 둘이 들어낸다',
  text:`석판 한 장이 헐겁다.<br><br>
    혼자 들면 떨어뜨린다. 무겁다.<br>
    둘이 들면 소리 없이 든다.<br><br>
    떨어뜨리면 소리가 크다.`,
  opts:[
    { l:'① 동료와 양쪽을 든다.', co:'sync',
      coOpt:{ ask:'저쪽 끝을 잡으십시오. 셋에 같이 듭니다. 손가락 조심하시고.', sec:60, p:1000,
        text:`떨어뜨리면 소리가 크다.`,
        doneText:`셋을 세고 같이 들었다. 소리가 거의 안 났다.<br><br>아래에 공간이 있다. 한 자쯤.<br>상자가 있다. 나무 상자.<br><br>안 열었다. 석판을 도로 덮었다. 덮을 때도 둘이 했다.<br>있다는 것만 알면 된다고 했다. 저쪽이 고개를 끄덕였다.`,
        failText:`혼자 들었다. 반쯤 들다 놓쳤다.<br><br>소리가 크게 울렸다. 홀 전체에.<br>엎드려서 한참 기다렸다.` },
      good:`소리 없이 들었다.`, bad:`떨어뜨렸다.`, flag:'liftedTogether' },
    { l:'② 빈 소리 나는 칸을 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`두드려 가며 빈 소리 순서를 짚었다. 여섯 칸.<br><br>맞췄다. 가운데로 갈수록 크게 울린다.<br>가운데 아래가 제일 넓다.<br><br>한 장이 아니라 여러 장 아래가 이어져 있다.`, flag:'connectedBelow',
      bad:`울림이 자리마다 바뀐다.<br><br>짚는 순간 다른 데가 운다.<br>그만뒀다.` }
  ] }
);

epicSlot('temple', 'digger').push(
{ title:'신전 — 둘이 층을 읽는다',
  text:`흙이 여덟 층이다.<br><br>
    혼자 보면 층이 몇인지 헷갈린다.<br>
    하나가 긁고 하나가 세면 안 헷갈린다.<br><br>
    긁는 쪽은 안 센다.`,
  opts:[
    { l:'① 동료가 센다.', co:'sync',
      coOpt:{ ask:'제가 옆면을 긁겠습니다. 색이 바뀔 때마다 말해 주십시오.', sec:60, p:1000,
        text:`긁으면서 세면 놓친다.`,
        doneText:`옆면을 조금씩 긁었다. 저쪽이 색 바뀌는 데를 셌다.<br><br>여덟이다. 다만 마지막 층이 두껍다. 나머지 일곱을 합친 만큼.<br>마지막 것만 깊이 묻었다.<br><br>여덟째가 다르다. 저쪽도 그렇게 말했다.<br>긁은 자리를 손으로 도로 발랐다.`,
        failText:`혼자 긁고 혼자 셌다.<br><br>긁다 보면 색이 섞인다. 몇 층인지 모르겠다.<br>일곱이었다가 아홉이 된다.` },
      good:`여덟을 셌다.`, bad:`못 셌다.`, flag:'eighthIsDeeper' },
    { l:'② 층 두께를 견준다.', mini:'scale', miniOpt:{ p:750, target:22, pool:[3,5,6,8,9,12] },
      good:`층마다 두께를 견줬다.<br><br>맞췄다. 일곱은 얇고 하나만 두껍다.<br>얇은 건 급히 묻은 것이고 두꺼운 건 공들인 것이다.<br><br>일곱을 급히 묻고 하나를 공들여 묻었다.`, flag:'sevenHastyOneCareful',
      bad:`두께가 안 잡힌다.<br><br>긁으면 층이 섞인다.<br>그만뒀다.` }
  ] }
);

epicSlot('forest', 'digger').push(
{ title:'검은 숲 — 둘이 내려 본다',
  text:`구덩이가 깊다. 키를 넘는다.<br><br>
    혼자 내려가면 못 나온다.<br>
    줄을 잡아 줄 사람이 있으면 다르다.<br><br>
    잡는 쪽이 더 힘들다.`,
  opts:[
    { l:'① 동료가 줄을 잡는다.', co:'standin',
      coOpt:{ ask:'줄을 잡아 주십시오. 두 번 당기면 올려 주시고.', sec:60, p:1050,
        text:`혼자 내려가면 못 나온다.`,
        doneText:`줄을 매고 내려갔다. 저쪽이 위에서 잡았다.<br><br>바닥에 닿았다. 비어 있다. 흙도 아니다. 돌바닥이다.<br>벽에 손자국이 있다. 위로 올라가려고 긁은 자국.<br><br>줄을 두 번 당겼다. 올라왔다.<br>저쪽 손이 벌겋다. 오래 잡고 있었다.`,
        failText:`줄을 나무에 묶고 혼자 내려갔다.<br><br>바닥까지 갔다. 올라오려니 줄이 미끄럽다.<br>세 번 미끄러지고 겨우 올라왔다. 손바닥이 갈라졌다.` },
      good:`손자국을 봤다.`, bad:`겨우 올라왔다.`, flag:'clawMarksInside' },
    { l:'② 벽의 곧기를 견준다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`벽 네 면의 기울기를 견줬다.<br><br>맞췄다. 전부 같다. 곧다.<br>손으로 판 구덩이는 이렇게 안 된다.<br><br>갈라진 것이다. 아래에서 벌어져 생겼다.`, flag:'splitOpen',
      bad:`면마다 기울기가 다르다.<br><br>재는 동안 바뀐다. 좁아지는 쪽으로.<br>그만뒀다.` }
  ] }
);

epicSlot('market', 'digger').push(
{ title:'장터 — 둘이 확인한다',
  text:`좌판 아래가 꺼졌다.<br><br>
    혼자 들추면 좌판이 기운다.<br>
    하나가 좌판을 받치고 하나가 아래를 봐야 한다.<br><br>
    기울면 주인이 안다.`,
  opts:[
    { l:'① 동료가 좌판을 받친다.', co:'sync',
      coOpt:{ ask:'좌판 모서리를 받쳐 주십시오. 기울면 안 됩니다.', sec:60, p:1000,
        text:`기울면 주인이 안다.`,
        doneText:`저쪽이 모서리를 받쳤다. 이쪽이 아래를 봤다.<br><br>흙이 꺼져 있다. 그 아래에 판자가 있다. 덮개다.<br>덮개 아래는 안 봤다.<br><br>주인은 고개를 안 들었다. 기울지 않아서 그렇다.<br>도로 내려놓았다. 조심해서.`,
        failText:`혼자 들췄다. 좌판이 기운다.<br><br>주인이 고개를 든다. 이쪽을 본다.<br>도로 내려놓았다. 한참 마주 보고 있었다.` },
      good:`덮개를 봤다.`, bad:`주인이 봤다.`, flag:'plankUnderStall' },
    { l:'② 꺼진 깊이를 견준다.', mini:'scale', miniOpt:{ p:750, target:18, pool:[2,3,5,6,8,9],
      },
      good:`꺼진 정도를 주변과 견줬다.<br><br>맞췄다. 손가락 두 마디 꺼졌다.<br>아래가 비면 그만큼 꺼진다. 한 자쯤 비었다.<br><br>사람 하나 누울 만한 데가 아래 있다.`, flag:'oneBodySpace',
      bad:`꺼진 데가 더 꺼진다.<br><br>재는 동안. 그만뒀다.` }
  ] }
);

epicSlot('lake', 'digger').push(
{ title:'거울 호수 — 둘이 따라간다',
  text:`메운 도랑이 이어진다.<br><br>
    혼자 따라가면 끊긴 데를 놓친다.<br>
    둘이 갈라져 짚으면 안 놓친다.<br><br>
    도랑은 한 줄이 아닐 수도 있다.`,
  opts:[
    { l:'① 동료와 갈라져 짚는다.', co:'sync',
      coOpt:{ ask:'저쪽 방향으로 짚어 가 주십시오. 다진 데만 따라가시면 됩니다.', sec:60, p:1000,
        text:`도랑은 한 줄이 아닐 수도 있다.`,
        doneText:`갈라져 따라갔다. 저쪽 것은 물가를 따라 돌다 끊겼다.<br><br>이쪽 것은 숲 쪽으로 간다. 두 줄이다.<br>합치면 갈래가 진다. 물가에서 시작해 둘로 갈린다.<br><br>둘 다 메워져 있다. 다 쓰고 메웠다.<br>어느 쪽이 먼저인지는 모르겠다.`,
        failText:`혼자 따라갔다. 숲 쪽으로 가는 한 줄만 봤다.<br><br>다른 줄이 있는지는 모른다.<br>끊긴 데까지 갔다가 돌아왔다.` },
      good:`두 줄을 봤다.`, bad:`한 줄만 봤다.`, flag:'twoChannels' },
    { l:'② 다진 깊이를 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`다진 정도로 순서를 짚었다. 여섯 자리.<br><br>맞췄다. 물가 쪽이 오래되고 숲 쪽이 새것이다.<br>물가에서 숲으로 파 갔다.<br><br>물에서 뭔가를 숲으로 옮겼다. 도랑으로.`, flag:'fromLakeToForest',
      bad:`다진 정도가 비슷하다.<br><br>순서를 못 잡겠다.<br>그만뒀다.` }
  ] }
);

epicSlot('tower', 'digger').push(
{ title:'탑 — 둘이 본다',
  text:`위에서 보면 메운 줄이 보인다.<br><br>
    혼자 보면 한 줄만 본다.<br>
    나눠 보면 몇 줄인지 나온다.<br><br>
    줄이 몇이냐가 중요하다.`,
  opts:[
    { l:'① 동료와 나눠 본다.', co:'sync',
      coOpt:{ ask:'반대쪽을 봐 주십시오. 땅 색이 다른 줄만 세시면 됩니다.', sec:60, p:1000,
        text:`줄이 몇이냐가 중요하다.`,
        doneText:`갈라 봤다. 저쪽이 넷, 이쪽이 넷.<br><br>여덟 줄이다. 전부 한 점에서 뻗는다. 숲 안쪽이다.<br>바퀴살 같다.<br><br>여덟 줄이면 여덟 번 팠다. 신전 흙 층도 여덟이었다.<br>수가 맞는다. 맞으면 대개 같은 일이다.`,
        failText:`혼자 봤다. 한쪽만 보인다.<br><br>넷까지 세고 못 셌다.<br>몇 줄인지 모른다.` },
      good:`여덟 줄을 셌다.`, bad:`넷만 셌다.`, flag:'eightSpokes' },
    { l:'② 기운 각도를 견준다.', mini:'scale', miniOpt:{ p:750, target:21, pool:[3,4,6,7,9,10] },
      good:`탑 기울기와 땅 꺼진 정도를 견줬다.<br><br>맞췄다. 기운 만큼 꺼졌다. 계산이 맞는다.<br>아래 굴 크기가 나온다. 방 하나쯤.<br><br>탑 바로 아래에 방이 있다. 굴이 아니라 방이다.`, flag:'roomNotTunnel',
      bad:`기울기가 계속 바뀐다.<br><br>재는 동안 더 기운다.<br>그만뒀다.` }
  ] }
);

epicSlot('ruin', 'digger').push(
{ title:'폐허 — 둘이 틈을 본다',
  text:`무너진 돌 사이에 틈이 있다.<br><br>
    혼자 들어가면 무너진다.<br>
    하나가 밖에서 돌을 잡아 주면 다르다.<br><br>
    잡는 쪽이 더 위험하다.`,
  opts:[
    { l:'① 동료가 돌을 받친다.', co:'standin',
      coOpt:{ ask:'이 돌을 받쳐 주십시오. 제가 어깨까지만 넣어 보겠습니다.', sec:60, p:1050,
        text:`혼자 들어가면 무너진다.`,
        doneText:`저쪽이 돌을 받쳤다. 어깨까지만 넣었다.<br><br>아래가 넓다. 손이 닿는 데가 없다.<br>바람이 분다. 어딘가로 통한다.<br><br>뺐다. 저쪽이 돌을 놓았다. 돌이 한 뼘 내려앉았다.<br>들어갔으면 못 나왔다. 어깨까지만 넣길 잘했다.`,
        failText:`혼자 넣었다. 돌을 손으로 받치면서.<br><br>손 하나로는 안 된다. 머리만 넣고 뺐다.<br>아래가 어둡다는 것만 알았다.` },
      good:`어깨까지 넣었다.`, bad:`머리만 넣었다.`, flag:'wideBelow' },
    { l:'② 꺼진 자리를 짚는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`꺼진 정도로 순서를 짚었다. 일곱 자리.<br><br>맞췄다. 가운데로 갈수록 깊다.<br>가운데 아래가 제일 넓다.<br><br>탑 아래 방과 크기가 비슷하다.`, flag:'similarSize',
      bad:`꺼진 데가 고르다.<br><br>순서를 못 잡겠다. 전체가 같이 꺼지는 중이다.<br>발을 옮겼다.` }
  ] }
);

epicSlot('road', 'digger').push(
{ title:'끊긴 길 — 둘이 재 본다',
  text:`땅이 어디까지 있는지 봐야 한다.<br><br>
    혼자 재면 앞으로 가게 된다.<br>
    하나가 뒤에서 잡으면 안 간다.<br><br>
    굴착꾼은 앞으로 가는 버릇이 있다.`,
  opts:[
    { l:'① 동료가 뒤에서 잡는다.', co:'standin',
      coOpt:{ ask:'제 허리띠를 잡아 주십시오. 제가 앞으로 가려 하면 당기시고.', sec:60, p:1050,
        text:`굴착꾼은 앞으로 가는 버릇이 있다.`,
        doneText:`허리띠를 잡히고 앞으로 나갔다. 삽으로 찔러 가며.<br><br>세 걸음에서 안 들어간다. 거기까지가 땅이다.<br>한 걸음 더 가려 했다. 저쪽이 당겼다.<br><br>끌려 왔다. 옷깃이 목을 조였다.<br>당겨 줘서 다행이었다. 한 걸음이 두 걸음이 됐을 것이다.`,
        failText:`혼자 재 봤다. 세 걸음.<br><br>한 걸음 더 갔다. 거기도 땅이었다.<br>또 한 걸음. 돌아보니 경계석이 멀었다.` },
      good:`세 걸음에서 멈췄다.`, bad:`더 갔다.`, flag:'heldBack' },
    { l:'② 삽으로 겨눠 찔러 본다.', mini:'aim', miniOpt:{ p:750, shots:3, need:2 },
      good:`손을 안 뻗고 삽만 뻗어 찔렀다. 두 번 닿았다.<br><br>안개 가장자리까지는 땅이다. 안쪽은 삽이 안 들어간다.<br>막힌 게 아니라 없다.<br><br>삽 길이만큼 떨어져서 쟀다. 손은 안 넣었다.`, flag:'probedWithSpade',
      bad:`세 번 다 삽이 빠진다.<br><br>안개 안쪽으로. 손에서 빠져나갔다.<br>삽을 잃었다.` }
  ] }
);
;

// ---------- epic-digger-3.js ----------
// ==========================================
// ★ 굴착꾼 확장 3/4
// index.html 에서 epic-digger-2.js 다음에 불러온다
// ==========================================

epicSlot('gate', 'digger').push(
{ title:'성문 — 안에서 메웠다',
  text:`메운 흙이 무르다.<br><br>
    안에서 다졌다는 뜻이다.<br>
    굴착꾼은 안에서 메우는 이유를 안다.<br><br>
    나가면서 뒤를 막는다. 쫓길 때 한다.`,
  opts:[
    { l:'① 어느 쪽으로 나갔는지 본다.', dc:13, kind:'sense', p:800,
      good:`메운 흙이 바깥쪽으로 밀려 있다.<br><br>안에서 밖으로 밀면서 메웠다.<br>안쪽에서 시작해 밖으로 나왔다는 뜻이다.<br><br>성 안에서 팠다. 성문 밖으로 나가려고.`, flag:'dugOutward',
      bad:`흙이 안쪽으로 밀려 있다.<br><br>밖에서 안으로 메웠다. 들어간 쪽이 막은 것이다.<br>들어가서 안 나왔다.`, poll:9 },
    { l:'② 메운 데를 판다.', dc:14, kind:'break', p:800,
      doom:{ title:'판 구멍', what:'아직 이어져 있습니다', dc:14, sec:70,
        text:`손으로 흙을 긁어냈다. 무르다. 금방 나온다.<br><br>구멍이 드러난다. 사람 하나 지날 만하다.<br>안쪽으로 이어진다. 안 막혔다. 메운 건 입구뿐이다.<br><br>굴착꾼은 뚫린 굴을 못 지나친다. 끝까지 가 봐야 안다.<br>기어 들어갔다. 뒤에서 흙이 도로 내려앉는다.`,
        dieText:`안에서 메운 굴은 안에서 다시 막힌다.<br><br>나가려고 막은 걸 들어오려고 뚫었다.<br>벽 밑동에 흙이 도로 메워져 있다.` },
      good:`손을 댔다가 거뒀다.<br><br>안에서 메운 것이다. 나가면서 막은 것이고 막은 데는 이유가 있다.<br>뚫으면 이어진다. 이어지면 들어가게 된다.<br><br>안 팠다. 위에 돌을 하나 얹어 뒀다.`, flag:'leftItSealed' }
  ] }
);

epicSlot('grave', 'digger').push(
{ title:'묘지 — 관 위의 덮개',
  text:`관 위에 나무판이 하나 더 있다.<br><br>
    관만으로 안 되는 경우에 덮개를 깐다.<br>
    굴착꾼은 그 경우를 안다.<br><br>
    관 뚜껑이 안에서 밀릴 때 깐다.`,
  opts:[
    { l:'① 덮개를 눌러 본다.', dc:13, kind:'sense', p:800,
      good:`손바닥으로 눌렀다. 단단하다. 안 움직인다.<br><br>다만 가운데가 조금 휘어 있다. 아래에서 밀어 올린 자국.<br>밀다 만 것이다. 지금은 안 민다.<br><br>덮개가 버텼다. 지금까지는.`, flag:'bowedPlank',
      bad:`누르니 아래에서 밀어 올린다.<br><br>같은 세기로. 손을 뗐다.`, poll:9 },
    { l:'② 덮개를 들어낸다.', dc:14, kind:'break', p:800,
      doom:{ title:'들어낸 덮개', what:'뚜껑이 밀립니다', dc:14, sec:70,
        text:`덮개를 들어냈다. 무겁다. 두껍다.<br><br>들어내자 관 뚜껑이 보인다. 흠집이 많다. 안에서 긁은 자국.<br>뚜껑이 한 뼘 밀린다. 덮개가 없어져서.<br><br>누르려는데 힘이 세다. 아래에서 미는 힘이다.<br>굴착꾼은 덮개를 왜 까는지 안다. 알면서 들어냈다.`,
        dieText:`덮개를 깐 데는 이유가 있다.<br><br>스물셋에 다 깔려 있었다. 이유가 스물셋이다.<br>봉분 하나가 열려 있다.` },
      good:`손을 댔다가 거뒀다.<br><br>덮개는 관이 안 될 때 까는 것이다. 들어내면 관만 남는다.<br>관만으로 안 되니까 덮개를 깐 것이다.<br><br>흙을 도로 덮었다. 파기 전보다 두껍게.`, flag:'reburiedDeeper' }
  ] }
);

epicSlot('village', 'digger').push(
{ title:'빈 마을 — 오래된 한 마당',
  text:`스물둘은 같은 날 팠다.<br><br>
    닫힌 집 마당만 훨씬 오래됐다.<br>
    굴착꾼은 시차를 본다.<br><br>
    먼저 판 데가 먼저 일어난 일이다.`,
  opts:[
    { l:'① 얼마나 오래됐는지 본다.', dc:13, kind:'gaze', p:800,
      good:`흙이 완전히 앉았다. 풀이 났다가 죽은 자국도 있다.<br><br>한 해는 넘는다.<br>나머지 스물둘보다 훨씬 먼저다.<br><br>여기가 먼저였다. 여기서 시작해 나중에 스물둘이 따라왔다.`, flag:'firstOne',
      bad:`흙 아래가 젖어 있다.<br><br>오래됐는데 젖어 있다. 아래에서 올라온다.<br>손을 털었다.`, poll:9 },
    { l:'② 파 본다.', dc:14, kind:'break', p:800,
      doom:{ title:'판 마당', what:'비어 있지 않았습니다', dc:14, sec:70,
        text:`단단한 흙을 팠다. 오래 걸렸다.<br><br>한 뼘, 두 뼘. 문패가 안 나온다.<br>세 뼘에서 뭔가 나온다. 문패가 아니다. 길다.<br><br>사람이다. 얕게가 아니라 깊게 묻혔다.<br>굴착꾼은 나온 것을 도로 못 넣는다. 나온 건 나온 것이다.`,
        dieText:`얕은 데는 물건이고 깊은 데는 사람이다.<br><br>깊으면 안 판다. 그게 규칙인데.<br>마당에 구덩이가 하나 있다.` },
      good:`두 뼘 파고 그만뒀다.<br><br>스물둘은 한 뼘에서 나왔다. 여기는 두 뼘에도 안 나온다.<br>깊으면 물건이 아니다.<br><br>도로 메웠다. 판 자국이 안 남게.`, flag:'stoppedAtTwo' }
  ] }
);

epicSlot('castle', 'digger').push(
{ title:'성 — 이어진 아래',
  text:`여러 석판 아래가 이어져 있다.<br><br>
    한 칸이 아니라 방이다.<br>
    굴착꾼은 방 크기를 소리로 안다.<br><br>
    가운데가 제일 넓다.`,
  opts:[
    { l:'① 가장자리를 짚어 크기를 잰다.', dc:13, kind:'sense', p:800,
      good:`울리는 칸과 안 울리는 칸의 경계를 짚었다.<br><br>둘러 보니 둥글다. 네모가 아니라 둥근 방이다.<br>둥근 방은 사람이 안 만든다. 모서리가 낭비라서.<br><br>둥글게 만든 데는 이유가 있다. 둘러싸려고 만든 것이다.`, flag:'roundRoom',
      bad:`경계가 움직인다.<br><br>울리던 데가 안 울리고 안 울리던 데가 운다.<br>크기를 못 쟀다.`, poll:9 },
    { l:'② 가운데 석판을 들어낸다.', dc:14, kind:'break', p:800,
      doom:{ title:'들어낸 가운데', what:'아래가 보였습니다', dc:14, sec:70,
        text:`가운데 석판을 들어냈다. 혼자서. 무거웠다.<br><br>아래가 보인다. 깊다. 홀 높이만큼.<br>바닥에 돌이 둥글게 놓여 있다. 스물셋 개.<br><br>가운데가 비어 있다. 위에서 보면 한눈에 들어온다.<br>굴착꾼은 아래를 내려다보는 게 일이다. 내려다보면 눈이 간다.`,
        dieText:`둥근 방은 위에서 보라고 만든 게 아니다.<br><br>가운데 것이 위를 보라고 만든 것이다.<br>홀 바닥에 석판이 한 장 빠져 있다.` },
      good:`손을 대다가 거뒀다.<br><br>둥근 방이다. 둘러싸려고 만든 것이다.<br>둘러싼 데를 위에서 들여다보면 가운데와 마주 본다.<br><br>가장자리 칸만 두드려 보고 그만뒀다.`, flag:'didntOpenCenter' }
  ] }
);

epicSlot('temple', 'digger').push(
{ title:'신전 — 여덟째 층',
  text:`일곱은 얇고 하나가 두껍다.<br><br>
    일곱을 급히 묻고 하나를 공들여 묻었다.<br>
    굴착꾼은 공들인 매장을 안다.<br><br>
    공들이면 아끼는 것이다.`,
  opts:[
    { l:'① 어느 쪽이 나중인지 본다.', dc:13, kind:'gaze', p:800,
      good:`두꺼운 층이 제일 아래다.<br><br>먼저 공들여 하나를 묻고 나중에 일곱을 급히 얹었다.<br>순서가 반대였다.<br><br>처음 하나가 중요했고 나머지 일곱은 그 위에 쌓은 것이다.`, flag:'firstWasCareful',
      bad:`두꺼운 층이 제일 위다.<br><br>마지막에 공들였다. 다시 보니 아래다.<br>볼 때마다 바뀐다.`, poll:9 },
    { l:'② 제일 아래까지 판다.', dc:15, kind:'break', p:850,
      doom:{ title:'판 바닥', what:'돌이 나왔습니다', dc:15, sec:70,
        text:`일곱 층을 지나 여덟째까지 팠다. 오래 걸렸다.<br><br>여덟째 층 아래에 돌이 있다. 판판하다. 뚜껑이다.<br>공들여 묻은 건 이 뚜껑이다. 아래에 든 게 아니라 뚜껑이.<br><br>뚜껑을 덮으려고 일곱을 얹은 것이다. 무게로 누르려고.<br>일곱을 치우면 뚜껑이 가벼워진다.`,
        dieText:`위에 쌓인 건 무게다.<br><br>무게를 치우면 눌려 있던 게 안 눌린다.<br>제단 아래에 흙이 한 층뿐이다.` },
      good:`세 층까지 파다 그만뒀다.<br><br>일곱이 위에 쌓여 있다. 쌓은 건 누르려고 쌓은 것이다.<br>치우면 안 눌린다.<br><br>판 층을 도로 덮었다. 원래대로 여덟 층으로.`, flag:'restoredLayers' }
  ] }
);

epicSlot('forest', 'digger').push(
{ title:'검은 숲 — 긁은 자국',
  text:`구덩이 벽에 손자국이 있다.<br><br>
    위로 올라가려고 긁은 자국이다.<br>
    굴착꾼은 그 자국을 안다. 못 나온 사람이 남긴다.<br><br>
    못 나왔으면 아래에 있어야 하는데 없다.`,
  opts:[
    { l:'① 자국 높이를 본다.', dc:13, kind:'sense', p:800,
      good:`바닥에서 한 팔 높이까지만 있다.<br><br>그 위로는 없다. 더 못 올라갔다.<br>다만 바닥에 아무것도 없다.<br><br>못 올라갔는데 없다. 위로 안 나갔으면 아래로 갔다.`, flag:'wentDownward',
      bad:`자국이 위까지 이어진다.<br><br>구덩이 입구까지. 올라왔다는 뜻이다.<br>올라와서 어디로 갔는지는 모른다.`, poll:9 },
    { l:'② 바닥을 파 본다.', dc:14, kind:'break', p:800,
      doom:{ title:'판 바닥', what:'이어졌습니다', dc:14, sec:70,
        text:`구덩이 바닥을 팠다. 돌바닥인 줄 알았는데 얇다.<br><br>깨졌다. 아래로 이어진다. 굴이다.<br>내려가는 굴이 아니라 옆으로 가는 굴이다.<br><br>숲 안쪽 방향이다. 굴착꾼은 이어진 굴을 못 지나친다.<br>줄이 짧다. 줄 없이 들어갔다.`,
        dieText:`이어진 굴은 끝까지 가야 이어진 줄 안다.<br><br>끝까지 가면 돌아올 줄이 모자란다.<br>구덩이 바닥에 구멍이 하나 있다.` },
      good:`삽을 댔다가 거뒀다.<br><br>바닥이 얇다. 깨면 이어질 것이다.<br>이어지면 들어가게 된다. 줄이 모자란다.<br><br>안 팠다. 올라왔다. 줄을 두 번 당겼다.`, flag:'didntBreakFloor' }
  ] }
);

epicSlot('market', 'digger').push(
{ title:'장터 — 좌판 아래 덮개',
  text:`꺼진 흙 아래에 판자가 있다.<br><br>
    묘지 관 위의 것과 같은 덮개다.<br>
    굴착꾼은 같은 덮개를 보면 같은 사람이 깔았다고 본다.<br><br>
    같은 이유로 깔았다는 뜻이기도 하다.`,
  opts:[
    { l:'① 나뭇결을 견준다.', dc:13, kind:'gaze', p:800,
      good:`결이 같다. 같은 나무에서 나왔다.<br><br>묘지 것과 여기 것이 한 나무다.<br>큰 나무였다. 스물셋 장쯤은 나왔을 것이다.<br><br>어디 나무인지는 알겠다. 숲에 그만한 게 있다.`, flag:'sameTreePlanks',
      bad:`결을 보는데 움직인다.<br><br>나이테가 돈다. 아주 천천히.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 덮개를 들춰 본다.', dc:14, kind:'break', p:800,
      doom:{ title:'들춘 덮개', what:'아래가 비어 있었습니다', dc:14, sec:70,
        text:`덮개를 한 뼘 들췄다. 아래를 보려고.<br><br>비어 있다. 흙도 아무것도 없다. 빈 공간이다.<br>사람 하나 누울 만하다.<br><br>덮개는 뭘 덮는 게 아니라 자리를 막는 것이다.<br>빈자리를 덮어 둔 것이다. 들추면 자리가 열린다.`,
        dieText:`덮어 둔 빈자리는 채워질 자리다.<br><br>덮개를 들추면 자리가 비었다는 걸 자리가 안다.<br>좌판이 하나 비었다.` },
      good:`손을 대다가 거뒀다.<br><br>덮개 아래가 비어 있을 것 같았다.<br>비어 있으면 채울 자리라는 뜻이다.<br><br>안 들췄다. 흙을 도로 덮었다.`, flag:'didntLiftPlank' }
  ] }
);

epicSlot('lake', 'digger').push(
{ title:'거울 호수 — 물에서 숲으로',
  text:`물가에서 숲으로 파 갔다.<br><br>
    도랑으로 뭔가 옮겼다.<br>
    굴착꾼은 도랑 폭으로 옮긴 것의 크기를 안다.<br><br>
    폭이 넓다.`,
  opts:[
    { l:'① 폭을 잰다.', dc:13, kind:'sense', p:800,
      good:`어깨 폭보다 넓다. 사람이 누워서 지날 만하다.<br><br>물건을 옮기는 도랑이 아니다. 사람 크기다.<br>끌었거나 흘려보냈거나.<br><br>바닥이 매끈하다. 여러 번 지났다.`, flag:'bodyWidth',
      bad:`폭이 안 잡힌다.<br><br>재는 동안 넓어진다. 손을 뗐다.`, poll:9 },
    { l:'② 도랑을 다시 판다.', dc:14, kind:'break', p:800,
      doom:{ title:'다시 판 도랑', what:'물이 왔습니다', dc:14, sec:70,
        text:`메운 도랑을 따라 팠다. 어디로 가는지 보려고.<br><br>무르다. 금방 파진다. 메운 흙이라 그렇다.<br>세 걸음쯤 파니 물이 스며든다.<br><br>물가와 이어졌다. 도랑이 다시 뚫린 것이다.<br>물이 온다. 도랑을 따라. 숲 쪽으로 가려던 물이 이쪽으로 온다.`,
        dieText:`메운 도랑은 다 쓰고 메운 것이다.<br><br>다시 파면 다시 쓰인다.<br>물가에서 숲으로 도랑이 하나 나 있다.` },
      good:`삽을 댔다가 거뒀다.<br><br>메운 건 다 썼다는 뜻이다. 다시 파면 다시 쓰인다.<br>무엇에 쓰였는지 모르는 걸 다시 쓰게 하면 안 된다.<br><br>안 팠다. 메운 자리에 돌을 얹어 뒀다.`, flag:'leftItFilled' }
  ] }
);

epicSlot('tower', 'digger').push(
{ title:'탑 — 아래의 방',
  text:`탑 바로 아래에 방이 있다.<br><br>
    굴이 아니라 방이다.<br>
    굴착꾼은 방과 굴을 가른다.<br><br>
    굴은 지나가는 데고 방은 있는 데다.`,
  opts:[
    { l:'① 들어가는 데를 찾는다.', dc:13, kind:'sense', p:800,
      good:`여덟 줄이 한 점에서 뻗는다. 그 점이 아니라 탑 쪽 끝을 봤다.<br><br>탑 밑동에 메운 자국이 있다. 성문 것과 같은 방식이다.<br>안에서 메웠다.<br><br>방에서 여덟 번 나갔다. 나갈 때마다 메웠다.`, flag:'eightExits',
      bad:`메운 자국이 아홉이다.<br><br>여덟 줄인데 아홉이다. 하나는 어디로 갔는지 안 보인다.<br>눈을 뗐다.`, poll:9 },
    { l:'② 탑 밑동을 판다.', dc:15, kind:'break', p:850,
      doom:{ title:'판 밑동', what:'방으로 들어갔습니다', dc:15, sec:70,
        text:`메운 자국을 팠다. 무르다. 안에서 메운 흙이다.<br><br>뚫렸다. 기어 들어갔다. 짧다. 바로 방이 나온다.<br>넓다. 벽에 금이 그어져 있다. 날짜를 센 것이다.<br><br>세어 보니 예순셋이다. 예순셋 날 여기 있었다.<br>굴착꾼은 방을 찾으면 들어간다. 들어가면 세어 본다. 세면 알게 된다.`,
        dieText:`여덟 번 나가고 아홉 번째는 안 나갔다.<br><br>나가는 데를 여덟 개 만들고도 안 나간 데는 이유가 있다.<br>탑 밑동이 메워져 있다.` },
      good:`삽을 댔다가 거뒀다.<br><br>여덟 번 나간 방이다. 여덟 번 나가고도 여기 있었다.<br>들어가면 왜 안 나갔는지 알게 된다.<br><br>안 팠다. 돌을 얹고 내려왔다.`, flag:'didntEnterRoom' }
  ] }
);

epicSlot('ruin', 'digger').push(
{ title:'폐허 — 같은 크기',
  text:`폐허 아래 빈 데가 탑 아래 방과 비슷하다.<br><br>
    같은 크기면 같은 사람이 팠다.<br>
    굴착꾼은 크기로 손을 안다.<br><br>
    같은 손이 두 군데를 팠다.`,
  opts:[
    { l:'① 둘을 견줘 본다.', dc:13, kind:'gaze', p:800,
      good:`둥글다. 둘 다 둥글다.<br><br>성 홀 아래도 둥글었다. 세 군데가 다 둥글다.<br>셋이 같은 크기, 같은 모양이다.<br><br>둘러싸는 방을 셋 만들었다. 셋이면 이유가 있다.`, flag:'threeRoundRooms',
      bad:`견주는데 크기가 달라진다.<br><br>폐허 것이 커진다. 탑 것도.<br>그만 봤다.`, poll:9 },
    { l:'② 틈으로 들어간다.', dc:15, kind:'evade', p:850,
      doom:{ title:'들어간 틈', what:'돌이 내려앉았습니다', dc:15, sec:70,
        text:`틈으로 몸을 넣었다. 어깨가 들어가고 허리가 들어갔다.<br><br>아래가 넓다. 발이 안 닿는다. 매달려 있다.<br>놓으면 떨어진다. 얼마나인지 모른다.<br><br>올라가려는데 위에서 돌이 내려앉는다. 어깨를 받치던 돌이다.<br>받쳐 줄 사람 없이 들어갔다.`,
        dieText:`혼자 들어가면 혼자 받쳐야 한다.<br><br>손이 둘인데 하나는 매달려야 한다.<br>폐허 틈이 막혔다.` },
      good:`머리를 넣다가 뺐다.<br><br>어깨까지만 넣었을 때 돌이 한 뼘 내려앉았다.<br>혼자면 받칠 사람이 없다.<br><br>안 들어갔다. 틈 앞에 돌을 쌓아 막았다.`, flag:'blockedTheGap' }
  ] }
);

epicSlot('road', 'digger').push(
{ title:'끊긴 길 — 세 걸음',
  text:`땅이 세 걸음까지다.<br><br>
    그다음은 삽이 안 들어간다.<br>
    굴착꾼은 안 들어가는 데를 처음 본다.<br><br>
    처음 보는 건 안 건드린다.`,
  opts:[
    { l:'① 세 걸음 앞에 표를 세운다.', dc:12, kind:'bond', p:800,
      good:`땅이 끝나는 데에 삽을 꽂았다. 세워서.<br><br>여기까지가 땅이라는 표다. 굴착꾼은 삽으로 표를 한다.<br>삽 하나를 두고 가는 셈이다.<br><br>아깝지만 표가 더 중요하다.`, flag:'plantedSpade' },
    { l:'② 한 걸음 더 가 본다.', dc:14, kind:'evade', p:800,
      doom:{ title:'간 한 걸음', what:'딛혔습니다', dc:14, sec:70,
        text:`네 걸음째를 디뎠다. 딛힌다.<br><br>삽은 안 들어가는데 발은 딛힌다. 이상하다.<br>이상한 건 확인해야 한다. 다섯 걸음째도 딛힌다.<br><br>여섯, 일곱. 돌아보니 삽이 멀다.<br>딛히는 만큼 가는 게 굴착꾼 버릇이다. 땅이 있으면 간다.`,
        dieText:`삽이 안 들어가는데 발이 딛히는 건 땅이 아니라는 뜻이다.<br><br>파 봐야 아는데 파지지가 않는다.<br>경계 앞에 삽이 하나 꽂혀 있다.` },
      good:`발을 올렸다가 내렸다.<br><br>삽이 안 들어가는데 발이 딛히면 땅이 아니다.<br>굴착꾼은 파지는 것만 땅으로 친다.<br><br>안 갔다. 삽을 꽂아 두고 돌아섰다.`, flag:'onlyDiggableIsGround' }
  ] }
);
;

