    { l:'② 좌판을 옮겨 준다.', dc:12, p:800,
      good:`좌판을 꺼진 데에서 비켜 놓았다.<br><br>주인이 옆에 앉아 있었으니 좌판도 옆이 낫다.<br>무겁지 않았다. 안이 비어 있다.<br><br>옮기고 보니 주인이 좌판 쪽으로 조금 움직였다. 따라왔다.`, flag:'movedTheStall',
      bad:`옮기는데 주인이 안 움직인다.<br><br>좌판만 옮겨졌다. 주인은 꺼진 데 옆에 그대로다.<br>도로 놓았다.`, poll:9 }
