epicSlot('gate', 'courier').push(
{ title:'성문 — 스물셋이 남았으니',
  text:`하나는 나가도 된다고 했다.<br><br>
    나가면 스물둘이 된다.<br>
    석상은 그 말에 대답을 안 했다.<br><br>
    전령은 안 한 대답을 중히 여긴다.`,
  opts:[
    { l:'① 다시 안 묻는다.', dc:13, kind:'evade', p:800,
      good:`안 물었다.<br><br>대답을 안 한 건 대답이 없다는 뜻이거나 말하면 안 된다는 뜻이다.<br>둘 다 더 물을 일이 아니다.<br><br>전령은 전할 말만 묻는다. 그 밖은 안 묻는다.`, flag:'didntPress',
      bad:`안 물으려는데 입이 움직인다.<br><br>물었다. 석상이 고개를 든다.<br>대답이 오기 전에 물러났다.`, poll:9 },
    { l:'② 나가도 되는 하나가 누구인지 묻는다.', dc:14, p:800,
      doom:{ title:'물은 것', what:'정해졌습니다', dc:14, sec:70,
        text:`누가 나가도 되냐고 물었다.<br><br>석상이 이쪽을 본다. 오래.<br>받침에 가로금이 하나 그어진다. 손도 안 댔는데.<br><br>물으면 정해진다. 안 물었으면 안 정해졌을 것이다.<br>나가도 되는 하나가 나가야 하는 하나가 됐다.`,
        dieText:`전령은 누구인지 묻는 게 일이다.<br><br>여기서는 그게 정하는 일이 된다.<br>받침에 가로금이 둘이다.` },
      good:`묻다가 그만뒀다.<br><br>누구냐고 물으면 정해진다.<br>안 정해진 채로 두는 게 낫다.<br><br>받는 사람을 묻는 것과 나갈 사람을 묻는 건 다르다. 이건 안 묻는다.`, flag:'leftItUndecided' }
  ] }
);

epicSlot('castle', 'courier').push(
{ title:'성 — 없던 종이',
  text:`함이 비어 있었는데 종이가 한 장 있다.<br><br>
    받는 사람 자리가 비어 있다.<br>
    전령은 받는 사람 없는 전언을 안 옮긴다.<br><br>
    옮기면 받는 사람이 정해진다.`,
  opts:[
    { l:'① 함에 그대로 둔다.', dc:12, kind:'bond', p:800,
      good:`도로 넣고 닫았다. 걸쇠를 걸었다.<br><br>함에 든 건 함이 맡은 것이다. 전령 몫이 아니다.<br>받는 사람이 오면 열어 가져갈 것이다.<br><br>안 오면 안 오는 대로 함이 맡고 있을 것이다.`, flag:'leftInBox' },
    { l:'② 받는 사람 자리를 채운다.', dc:14, p:800,
      doom:{ title:'채운 이름', what:'받는 사람이 생겼습니다', dc:14, sec:70,
        text:`빈 자리에 이름을 적었다. 아무 이름이나. 마을에서 본 것으로.<br><br>적자 종이가 무거워진다. 전할 데가 생겨서 그렇다.<br>전령은 받는 사람이 정해진 걸 못 두고 간다.<br><br>들고 나섰다. 적은 이름을 찾아야 한다.<br>그 이름이 어디 있는지는 아무도 모른다.`,
        dieText:`받는 사람을 적으면 전할 데가 생긴다.<br><br>없는 사람을 적으면 없는 데로 가야 한다.<br>함이 비어 있다.` },
      good:`붓을 들었다가 놓았다.<br><br>빈 자리에 이름을 적으면 받는 사람이 생긴다.<br>없는 사람을 적으면 없는 데로 가야 한다.<br><br>비워 뒀다. 비어 있어야 안 옮긴다.`, flag:'leftBlankField' }
  ] }
);

epicSlot('village', 'courier').push(
{ title:'빈 마을 — 문틈의 종이',
  text:`닫힌 집 문 밑에 종이 귀가 나와 있다.<br><br>
    들어 있는 것이다.<br>
    전령은 들어간 걸 안 뽑는다. 들어갔으면 전해진 것이다.<br><br>
    뽑으면 안 전해진 게 된다.`,
  opts:[
    { l:'① 안 뽑고 밀어 넣는다.', dc:12, kind:'bond', p:800,
      good:`나온 귀를 안쪽으로 밀어 넣었다.<br><br>완전히 들어갔다. 이제 안 보인다.<br>전해진 것이다. 받았는지는 모르지만 전해졌다.<br><br>전령은 전한 데까지가 일이다. 받는 건 받는 쪽 일이다.`, flag:'pushedItIn',
      bad:`밀었는데 안 들어간다.<br><br>안쪽에서 뭔가가 막고 있다. 종이가 쌓여 있는 것이다.<br>여러 장이다. 아무도 안 가져갔다는 뜻이다.<br><br>밀어 넣던 손을 뗐다. 귀는 그대로 나와 있다.`, poll:6 },
    { l:'② 뽑아 본다.', dc:14, p:800,
      doom:{ title:'뽑은 종이', what:'안 전해진 것이 됐습니다', dc:14, sec:70,
        text:`귀를 잡고 당겼다. 쉽게 빠진다.<br><br>펴 보니 받는 사람 자리에 이름이 있다. 읽었다.<br>읽고 나니 그 이름을 찾아야 한다.<br><br>뽑았으니 안 전해진 것이다. 안 전해진 건 전령이 들고 다닌다.<br>들고 다니면 무거워진다. 전령은 무거워지면 못 달린다.`,
        dieText:`들어간 건 전해진 것이다.<br><br>뽑으면 도로 전령 것이 된다.<br>문 밑에 종이 귀가 나와 있다.` },
      good:`손을 댔다가 거뒀다.<br><br>들어간 건 전해진 것이다. 뽑으면 안 전해진 게 된다.<br>안 전해진 건 전령 몫이다.<br><br>안 뽑았다. 밀어 넣기만 했다.`, flag:'didntPullIt' }
  ] }
);

epicSlot('market', 'courier').push(
{ title:'장터 — 네 귀가 눌린 한 장',
  text:`맨 아래 한 장만 네 귀가 다 눌려 있다.<br><br>
    떼지 말라는 뜻이다.<br>
    전령은 네 귀로 붙인 걸 안 뗀다.<br><br>
    떼라고 붙인 게 아니다.`,
  opts:[
    { l:'① 그대로 둔다.', dc:12, kind:'evade', p:800,
      good:`위에 붙은 것들만 보고 그 한 장은 안 건드렸다.<br><br>네 귀로 붙인 건 여기 두라는 뜻이다.<br>여기 두라는 건 여기 있어야 한다는 뜻이다.<br><br>기둥에 남겨 뒀다.`, flag:'leftItPinned',
      bad:`위 것들을 보다가 손이 아래로 간다.<br><br>한 귀를 눌러 봤다. 단단하다.<br>손을 뗐다.`, poll:9 },
    { l:'② 떼어 본다.', dc:14, p:800,
      doom:{ title:'뗀 종이', what:'기둥이 비었습니다', dc:14, sec:70,
        text:`네 귀를 하나씩 떼어 냈다. 단단히 붙어 있다.<br><br>마지막 귀가 떨어지자 위의 스물셋 장이 전부 떨어진다.<br>맨 아래 것이 나머지를 붙들고 있었다.<br><br>기둥이 비었다. 붙은 게 하나도 없다.<br>빈 기둥에는 붙일 게 필요하다. 전령이 붙인다. 전령이 붙일 게 없으면 자기를 붙인다.`,
        dieText:`맨 아래 것은 받침이었다.<br><br>받침을 떼면 전부 떨어진다.<br>기둥에 한 장이 붙어 있다. 네 귀가 눌린 채로.` },
      good:`손을 댔다가 거뒀다.<br><br>네 귀가 눌린 건 안 뗀다. 전령 규칙이다.<br>맨 아래 것은 받침일 수도 있다.<br><br>안 뗐다. 위 것들만 세고 갔다.`, flag:'didntUnpinIt' }
  ] }
);

epicSlot('forest', 'courier').push(
{ title:'검은 숲 — 안쪽을 향한 표식',
  text:`전령 표식이 안쪽을 향한다.<br><br>
    안쪽으로 가라는 배치다.<br>
    전령은 표식을 믿는다. 같은 직업이 남긴 것이라서.<br><br>
    다만 믿는 게 여기서는 위험하다.`,
  opts:[
    { l:'① 누가 남겼는지 본다.', dc:13, kind:'sense', p:800,
      good:`새긴 깊이가 고르다. 한 사람이 남겼다.<br><br>다만 손이 익지 않았다. 전령 표식을 아는데 새기는 건 서툴다.<br>배우기만 하고 안 써 본 사람이다.<br><br>전령이 아니면서 전령 표식을 쓴 것이다.`, flag:'notACourier',
      bad:`새긴 손이 익었다.<br><br>오래 쓴 손이다. 전령이 맞다.<br>전령이 안쪽으로 가라고 했다.`, poll:9 },
    { l:'② 표식대로 간다.', dc:14, kind:'evade', p:800,
      doom:{ title:'따라간 표식', what:'안쪽으로 갔습니다', dc:14, sec:70,
        text:`표식을 따라 안쪽으로 걸었다. 전령은 표식을 믿는다.<br><br>트인 줄이 이어진다. 걷기 좋다.<br>표식이 계속 나온다. 스물셋째까지 세었다.<br><br>스물넷째가 없다. 거기서 길이 끝난다.<br>표식은 앞사람이 남기는 것이다. 앞사람이 거기까지 갔다는 뜻이다.`,
        dieText:`표식이 끝나는 데가 앞사람이 끝난 데다.<br><br>따라가면 같은 데서 끝난다.<br>숲에 표식이 스물넷 개다.` },
      good:`표식을 등지고 돌아섰다.<br><br>전령 표식을 안 쓰는 사람이 남겼다. 배우기만 하고 안 써 본 손이다.<br>표식을 흉내 내는 건 전령을 부르려는 것이다.<br><br>안 갔다. 가장자리로 돌았다.`, flag:'ignoredTheMarks' }
  ] }
);

epicSlot('temple', 'courier').push(
{ title:'신전 — 전령이 놓고 간 것',
  text:`세 번 접힌 종이다.<br><br>
    전령이 접는 방식이다.<br>
    못 전해서 놓고 간 것이다.<br><br>
    전령이 놓고 갔으면 못 전한 것이다.`,
  opts:[
    { l:'① 그대로 둔다.', dc:12, kind:'bond', p:800,
      good:`안 건드렸다.<br><br>못 전한 걸 놓고 간 데는 이유가 있다. 여기 두면 전해진 것으로 친다.<br>전령끼리 아는 방식이다. 마지막에 하는 것이다.<br><br>옆에 백지를 한 장 놓았다. 같이 놓으면 둘이 놓은 게 된다.`, flag:'honoredTheDrop' },
    { l:'② 펴 본다.', dc:14, kind:'gaze', p:800,
      doom:{ title:'편 종이', what:'받는 사람이 있었습니다', dc:14, sec:70,
        text:`세 번 접힌 걸 폈다.<br><br>받는 사람 자리에 이름이 있다. 보낸 사람 자리에도 있다.<br>둘 다 있으면 전할 수 있는 전언이다.<br><br>전할 수 있는 걸 못 전하고 놓고 갔다는 뜻이다.<br>전령은 전할 수 있는 걸 못 지나친다. 받는 사람 이름을 읽었다. 이제 안다.`,
        dieText:`놓고 간 데는 이유가 있다.<br><br>읽으면 이유가 없어진다.<br>제단에 종이가 한 장 있다. 세 번 접힌 채로.` },
      good:`펴려다 도로 놓았다.<br><br>전령이 놓고 갔으면 못 전한 것이다.<br>못 전한 걸 펴면 전할 수 있는 게 된다.<br><br>안 폈다. 세 번 접힌 채로 뒀다.`, flag:'didntUnfold' }
  ] }
);

epicSlot('grave', 'courier').push(
{ title:'묘지 — 놓였다 없어진 것',
  text:`비석 앞에 네모난 자국이 있다.<br><br>
    종이가 놓였다 없어졌다.<br>
    전령은 놓고 간 게 없어지는 걸 안다.<br><br>
    받는 쪽이 가져갔다는 뜻이다.`,
  opts:[
    { l:'① 스물셋에 다 있는지 본다.', dc:13, kind:'gaze', p:800,
      good:`스물셋 다 있다. 다 놓였고 다 없어졌다.<br><br>스물셋이 다 받았다. 받는 쪽이 있었다는 뜻이다.<br>전령은 받은 걸 확인하면 일이 끝난다.<br><br>끝난 일이다. 다만 놓고 간 전령은 어떻게 됐는지 모르겠다.`, flag:'allReceived',
      bad:`하나만 자국이 없다.<br><br>거기만 안 놓였다. 스물둘만 놓였다.<br>왜 하나를 빼놓았는지 모르겠다.`, poll:9 },
    { l:'② 이쪽 것이 없어지는지 본다.', dc:14, p:800,
      doom:{ title:'지켜본 것', what:'가져가는 걸 봤습니다', dc:14, sec:70,
        text:`놓아 둔 백지를 지켜봤다. 없어지나 보려고.<br><br>한참 있었다. 움직인다. 돌 아래에서 종이가 빠져나간다.<br>아래로 빨려 들어간다. 흙 속으로.<br><br>받는 쪽이 아래에 있다. 보고 나니 안다.<br>전령은 받는 쪽을 확인하는 게 일이다. 확인했으니 다음엔 직접 전해야 한다.`,
        dieText:`받는 쪽을 보면 다음엔 손에 쥐여 줘야 한다.<br><br>그게 전령의 방식이다.<br>비석 앞에 백지가 스물셋 장이다.` },
      good:`놓고 돌아섰다.<br><br>없어지는지는 안 봤다. 보면 받는 쪽을 알게 된다.<br>알면 다음엔 직접 전해야 한다.<br><br>안 봤다. 놓는 데까지가 일이다.`, flag:'didntWatch' }
  ] }
);

epicSlot('tower', 'courier').push(
{ title:'탑 — 메운 자국을 길로 봤다',
  text:`동료가 길로 본 것이 메운 자국이었다.<br><br>
    전령은 길과 길 아닌 것을 가른다.<br>
    다만 위에서 보면 비슷하다.<br><br>
    길처럼 보이는 건 길이 될 수도 있다.`,
  opts:[
    { l:'① 다른 것도 있는지 본다.', dc:13, kind:'sense', p:800,
      good:`메운 자국이 여덟 줄이다. 길은 다섯 갈래다.<br><br>합치면 열셋. 다만 메운 자국은 길이 아니다.<br>길은 다섯뿐이고 전부 성문으로 간다.<br><br>여덟 줄은 아래로 가는 것이다. 위로 다니는 길이 아니다.`, flag:'fiveRoadsEightLines',
      bad:`메운 자국이 길과 이어진다.<br><br>한 군데서. 길이 아래로 이어지는 데가 있다.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 길로 쳐서 외운다.', dc:14, p:800,
      doom:{ title:'외운 길', what:'길이 됐습니다', dc:14, sec:70,
        text:`여덟 줄을 길로 쳐서 외웠다. 열셋 갈래로.<br><br>전령이 외운 길은 길이 된다. 외운 대로 발이 간다.<br>내려와서 걸었다. 외운 대로 갔다.<br><br>여덟 줄 중 하나로 발이 들어선다. 길이 아닌데 길처럼 걸린다.<br>아래로 간다. 전령은 외운 길을 안 벗어난다.`,
        dieText:`전령이 외우면 길이 된다.<br><br>길이 아닌 걸 외우면 길이 아닌 데로 간다.<br>메운 자국이 아홉 줄이다.` },
      good:`다섯만 외웠다.<br><br>메운 자국은 길이 아니다. 길처럼 보여도 아니다.<br>전령이 외운 건 길이 된다. 그래서 가려서 외운다.<br><br>여덟 줄은 안 외웠다. 있다는 것만 적어 뒀다.`, flag:'memorizedFiveOnly' }
  ] }
);

epicSlot('lake', 'courier').push(
{ title:'거울 호수 — 기다리는 자세',
  text:`비친 것이 내민 채로 기다린다.<br><br>
    전령은 기다리는 걸 잘한다.<br>
    받을 사람이 올 때까지 기다린다.<br><br>
    저쪽도 전령이면 오래 기다릴 것이다.`,
  opts:[
    { l:'① 물가를 떠난다.', dc:13, kind:'evade', p:800,
      good:`등을 돌리고 걸었다. 뛰지 않았다.<br><br>뛰면 쫓아온다. 전령은 뛰는 걸 보면 따라 뛴다.<br>보통 걸음으로 갔다.<br><br>스무 걸음쯤에서 뒤에서 물소리가 났다. 안 돌아봤다.`, flag:'walkedAwayFromIt',
      bad:`걷는데 발이 빨라진다.<br><br>전령 몸이 그렇다. 뛰려고 한다.<br>억지로 늦췄다.`, poll:9 },
    { l:'② 얼마나 기다리나 본다.', dc:14, p:800,
      doom:{ title:'지켜본 것', what:'같이 기다렸습니다', dc:14, sec:70,
        text:`물가에 앉아 지켜봤다. 저쪽이 언제 포기하나 보려고.<br><br>안 포기한다. 계속 내밀고 있다.<br>해가 안 움직이니 시간도 안 간다.<br><br>이쪽도 안 일어선다. 기다리는 걸 잘해서 그렇다.<br>둘 다 전령이면 둘 다 안 일어선다. 먼저 일어서는 쪽이 지는 게 아니라 사는 것이다.`,
        dieText:`전령은 기다리는 걸 제일 잘한다.<br><br>잘하는 게 여기서는 나쁘다.<br>물가에 앉은 것이 하나 있다. 비친 쪽에도 하나.` },
      good:`일어섰다.<br><br>기다리기 시작하면 안 일어선다. 전령 몸이 그렇게 배웠다.<br>앉기 전에 일어서는 게 낫다.<br><br>앉지도 않았다. 서서 보고 돌아섰다.`, flag:'didntSitToWait' }
  ] }
);

epicSlot('ruin', 'courier').push(
{ title:'폐허 — 왜 안 되게 됐는가',
  text:`쉬어도 된다는 표식에 가로줄이 쳐졌다.<br><br>
    이제 안 된다는 뜻이다.<br>
    전령은 왜 안 되게 됐는지 안 적는다.<br><br>
    적으면 확인하러 간다.`,
  opts:[
    { l:'① 표식만 보고 지난다.', dc:12, kind:'evade', p:800,
      good:`안 된다는 것만 알고 지났다.<br><br>이유를 찾으면 찾게 된다. 찾으면 알게 되고 알면 늦는다.<br>전령은 표식만 보고 판단한다.<br><br>쉬지 않고 지났다. 다리가 아팠다.`, flag:'obeyedTheMark',
      bad:`지나는데 자꾸 돌아보게 된다.<br><br>왜 안 되는지가 걸린다. 세 번 돌아봤다.<br>세 번 다 아무것도 없었다.`, poll:9 },
    { l:'② 기댄 자리에 앉아 본다.', dc:14, p:800,
      doom:{ title:'앉은 자리', what:'일어설 수가 없습니다', dc:14, sec:70,
        text:`제일 깊이 닳은 자리에 앉았다. 작은 사람이 오래 앉았던 자리.<br><br>편하다. 등이 딱 맞는다. 다리를 펴니 더 편하다.<br>오래 달린 다리가 놓인다.<br><br>일어서려는데 안 일어서진다. 다리가 아니라 마음이 안 선다.<br>전령이 앉으면 일어나기 어렵다. 그래서 가로줄을 친 것이다.`,
        dieText:`쉬어도 된다는 표에 가로줄이 쳐진 데는 이유가 있다.<br><br>여기서 쉬면 못 일어선다.<br>닳은 자리가 하나 늘었다.` },
      good:`앉으려다 섰다.<br><br>가로줄이 쳐진 데는 이유가 있다. 이유는 안 적혀 있다.<br>안 적힌 이유는 대개 앉으면 알게 되는 것이다.<br><br>서서 다리를 주물렀다. 그것으로 됐다.`, flag:'stayedStanding' }
  ] }
);

epicSlot('road', 'courier').push(
{ title:'끊긴 길 — 두 발이 나란한 자국',
  text:`마지막 자국이 두 발이 나란하다.<br><br>
    멈춰 섰다는 뜻이다.<br>
    전령은 멈춰 서는 자세를 안다.<br><br>
    전할 걸 꺼낼 때 그렇게 선다.`,
  opts:[
    { l:'① 멀리서 본다.', dc:13, kind:'gaze', p:800,
      good:`멀리서 보니 자국 앞쪽에 뭔가 눌린 자국이 있다.<br><br>작고 네모나다. 종이가 놓였던 자국이다.<br>거기서 꺼내 놓았다.<br><br>놓고 나서 없어졌다. 전한 것이다. 받는 쪽이 저기 있었다.`, flag:'deliveredThere',
      bad:`눌린 자국이 이쪽으로 이어진다.<br><br>놓인 자국이 여럿이다. 경계석 쪽으로.<br>눈을 돌렸다.`, poll:9 },
    { l:'② 같은 자세로 서 본다.', dc:14, p:800,
      doom:{ title:'선 자세', what:'꺼내게 됐습니다', dc:14, sec:70,
        text:`경계 앞에서 두 발을 나란히 했다. 그 자세로.<br><br>몸이 안다. 전할 걸 꺼내는 자세다.<br>손이 품으로 간다. 백지를 꺼낸다.<br><br>꺼내면 놓아야 한다. 놓으면 받는 쪽이 온다.<br>전령은 꺼낸 걸 도로 안 넣는다. 그게 규칙이다.`,
        dieText:`자세를 잡으면 몸이 따라 한다.<br><br>전령 몸은 꺼내고 놓는 걸 먼저 배운다.<br>안개 앞에 자국이 둘이다. 두 발씩 나란하다.` },
      good:`발을 모으려다 말았다.<br><br>두 발이 나란하면 꺼내는 자세다. 몸이 먼저 한다.<br>꺼내면 놓고 놓으면 받는 쪽이 온다.<br><br>한 발을 뒤로 뺐다. 그러면 자세가 안 된다.`, flag:'brokeTheStance' }
  ] }
);
